@using sv_a6fbf369847442ebb667b384f6ff212f.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State

<select class="form-select form-select-sm" style="width:200px"
        value="@State.SelectedWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in _warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private readonly record struct Warehouse(string Id, string Name);

    private static readonly Warehouse[] _warehouses =
    [
        new("WH-001", "Warehouse A"),
        new("WH-002", "Warehouse B"),
        new("WH-003", "Warehouse C"),
    ];

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
