@page "/dashboard"
@using sv_a6fbf369847442ebb667b384f6ff212f.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Warehouse: <strong>@State.SelectedWarehouseId</strong>
        </p>
        <p class="card-text">
            Items below minimum level:
            <span class="badge @BadgeClass fs-5">@State.LowStockCount</span>
        </p>
        <p class="text-muted small">Refreshes every 10 seconds.</p>
    </div>
</div>

@code {
    private Timer? _pollTimer;

    private string BadgeClass => State.LowStockCount > 0 ? "bg-danger" : "bg-success";

    protected override async Task OnInitializedAsync()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;

        // Initial fetch
        await PollAlerts();

        // Start polling every 10 seconds
        _pollTimer = new Timer(async _ => await PollAlerts(), null,
            TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(10));
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh when warehouse changes
        await PollAlerts();
    }

    private void OnAlertCountChanged() => InvokeAsync(StateHasChanged);

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(State.SelectedWarehouseId);
        // Setting the property fires OnAlertCountChanged, notifying ALL subscribers
        State.LowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _pollTimer?.Dispose();
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

